.big-title {
  font-size: 5rem;
  color: yellow;
  font-family: cursive;
}

.margin-50 {
  margin: 50px;
}

$("h1").css("color", "green");        // set
console.log($("h1").css("color"));    // get -> rgb(...)
console.log($("h1").css("font-size")); // get -> e.g. 32px

$("h1").addClass("big-title margin-50");
$("h1").removeClass("big-title");
console.log($("h1").hasClass("margin-50")); // true
